dashboard.definition:
{
	"title": "Secure Infrastructure",
	"description": "Unify infrastructure assurance, exposure, and operational control signals.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Secure Infrastructure",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/secure-infrastructure.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# Secure Infrastructure\nUnify infrastructure assurance, exposure, and operational control signals."
			}
		},
		"viz_infra_sdwan_edges": {
			"type": "splunk.singlevalue",
			"title": "SD-WAN Edge Sites",
			"dataSources": {
				"primary": "ds_infra_sdwan_edge_count"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('sdwan_site_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#53bfff"
			},
			"description": "Total count of unique Cisco Catalyst SD-WAN sites actively reporting health telemetry, providing the WAN edge infrastructure footprint KPI."
		},
		"viz_infra_dc_anomaly_count": {
			"type": "splunk.singlevalue",
			"title": "DC Fabric Anomalies",
			"dataSources": {
				"primary": "ds_infra_dc_anomalies"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('anomaly_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#ff9a4a"
			},
			"description": "Total count of fabric anomalies detected by Cisco Nexus Dashboard , with unique fabric count and count of critical/high severity entities, providing the primary DC network health KPI."
		},
		"viz_infra_dc_advisory_count": {
			"type": "splunk.singlevalue",
			"title": "DC Security Advisories",
			"dataSources": {
				"primary": "ds_infra_dc_advisories"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('advisory_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#ff7169"
			},
			"description": "Count of active security advisories from Cisco Nexus Dashboard , including unique advisory IDs and critical-severity advisory count, providing the DC vulnerability posture KPI."
		},
		"viz_infra_rogue_ap_count": {
			"type": "splunk.singlevalue",
			"title": "Rogue APs",
			"dataSources": {
				"primary": "ds_infra_rogue_ap_count"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('rogue_ap_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#ff7169"
			},
			"description": "Total count of unique rogue access points detected by Cisco Meraki Air Marshal , providing the wireless threat detection KPI for the Secure Infrastructure pillar."
		},
		"viz_infra_dc_trend": {
			"type": "splunk.area",
			"title": "DC Health Signals Trend",
			"dataSources": {
				"primary": "ds_infra_dc_trend"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#ff9a4a",
					"#ff7169"
				],
				"stackMode": "stacked",
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			},
			"description": "Hourly trend combining Cisco Nexus Dashboard anomalies and security advisories as a unified DC health signal, enabling operators to correlate infrastructure health degradation with specific time windows."
		},
		"viz_infra_sdwan_apps": {
			"type": "splunk.bar",
			"title": "SD-WAN Application Health",
			"dataSources": {
				"primary": "ds_infra_sdwan_apps_health"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#8bd45b",
					"#ff9a4a",
					"#ff7169",
					"#64748b"
				]
			},
			"description": "Distribution of Cisco Catalyst SD-WAN sites by application health status , showing how many sites report good, fair, poor, or no-data application experience quality across the WAN fabric."
		},
		"viz_infra_status_rollup": {
			"type": "splunk.table",
			"title": "Infrastructure Status Rollup",
			"dataSources": {
				"primary": "ds_infra_status_rollup"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Rolls up Secure Infrastructure posture from Catalyst Center device health, inventory, and compliance records."
		},
		"viz_infra_psirt_exposure": {
			"type": "splunk.table",
			"title": "PSIRT Exposure by Site and Family",
			"dataSources": {
				"primary": "ds_infra_psirt_exposure"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Ranks PSIRT exposure by site/location and device family using Catalyst Center advisory records."
		},
		"viz_infra_software_versions": {
			"type": "splunk.bar",
			"title": "Software Version Mix",
			"dataSources": {
				"primary": "ds_infra_software_versions"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "off",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#53bfff"
				]
			},
			"description": "Groups managed devices by device family and software version from Catalyst Center inventory, providing the version-distribution baseline needed to flag devices approaching End of Life/End of Support (LDOS)."
		},
		"viz_infra_rogue_containment": {
			"type": "splunk.column",
			"title": "Rogue AP Containment",
			"dataSources": {
				"primary": "ds_infra_rogue_containment"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#8bd45b",
					"#ff7169"
				],
				"stackMode": "stacked"
			},
			"description": "Per-SSID breakdown of Cisco Meraki Air Marshal rogue AP containment status , showing which networks have contained vs uncontained rogue APs to prioritize manual response where auto-containment is insufficient."
		},
		"viz_infra_secure_endpoint_incidents": {
			"type": "splunk.table",
			"title": "Secure Endpoint Incidents and Malware",
			"dataSources": {
				"primary": "ds_infra_secure_endpoint_incidents"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Ranks Cisco Secure Endpoint incidents and malware detections by severity, disposition, threat, endpoint, and user."
		},
		"viz_infra_duo_blocked_posture": {
			"type": "splunk.table",
			"title": "Duo Blocked Posture and Identity Events",
			"dataSources": {
				"primary": "ds_infra_duo_blocked_posture"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Combines Duo denied identity decisions with current endpoint posture failures such as missing encryption, firewall, password, or trust controls."
		},
		"viz_infra_duo_application_access": {
			"type": "splunk.table",
			"title": "Duo Application Access: Who, Where, and When",
			"dataSources": {
				"primary": "ds_infra_duo_application_access"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 25,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Answers which Duo-protected applications were accessed, by whom, from where, and when , including factor and outcome."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Infrastructure, NetOps, and network-security teams  •  **Sources:** Catalyst Center, Catalyst SD-WAN, Nexus Dashboard, and Meraki  •  **Reading guide:** Use footprint and anomaly KPIs to orient, then review trends and detailed rollups.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Infrastructure assurance\nUse footprint and anomaly KPIs to orient, then review trends and detailed rollups."
			}
		}
	},
	"dataSources": {
		"ds_infra_sdwan_edge_count": {
			"name": "Secure Networking - Infrastructure SD-WAN Edge Site Count",
			"options": {
				"ref": "secure_networking_infra_sdwan_edge_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_dc_anomalies": {
			"name": "Secure Networking chain - DC anomaly count",
			"options": {
				"ref": "secure_networking_dc_anomaly_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_dc_advisories": {
			"name": "Secure Networking chain - DC advisory count",
			"options": {
				"ref": "secure_networking_dc_advisory_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_rogue_ap_count": {
			"name": "Secure Networking chain - rogue AP count",
			"options": {
				"ref": "secure_networking_meraki_rogue_ap_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_dc_trend": {
			"name": "Secure Networking chain - DC health signal trend",
			"options": {
				"ref": "secure_networking_dc_health_signals_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_sdwan_apps_health": {
			"name": "Secure Networking - SD-WAN Application Health Breakdown",
			"options": {
				"ref": "secure_networking_sdwan_apps_health_breakdown",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_status_rollup": {
			"name": "Secure Networking - Secure Infrastructure Status Rollup",
			"options": {
				"ref": "secure_networking_secure_infra_status_rollup",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_psirt_exposure": {
			"name": "Secure Networking - PSIRT Exposure by Site and Family",
			"options": {
				"ref": "secure_networking_psirt_exposure_by_site_family",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_software_versions": {
			"name": "Secure Networking - Catalyst Center Software Version Inventory",
			"options": {
				"ref": "secure_networking_catalyst_center_software_version_inventory",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_rogue_containment": {
			"name": "Secure Networking chain - rogue containment",
			"options": {
				"ref": "secure_networking_meraki_rogue_ap_containment",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_secure_endpoint_incidents": {
			"name": "Secure Networking - Secure Endpoint Incident and Malware Activity",
			"options": {
				"ref": "secure_networking_infra_secure_endpoint_incidents",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_duo_blocked_posture": {
			"name": "Secure Networking - Duo Blocked Posture and Identity Events",
			"options": {
				"ref": "secure_networking_infra_duo_blocked_posture_identity",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_infra_duo_application_access": {
			"name": "Secure Networking - Duo Application Access Detail",
			"options": {
				"ref": "secure_networking_infra_duo_application_access",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 2002,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 88
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 14,
							"w": 56,
							"h": 56
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 108,
							"y": 4,
							"w": 1292,
							"h": 76
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 100,
							"w": 1400,
							"h": 64
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 176,
							"w": 1400,
							"h": 54
						},
						"type": "block"
					},
					{
						"item": "viz_infra_sdwan_edges",
						"position": {
							"x": 20,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_infra_dc_anomaly_count",
						"position": {
							"x": 375,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_infra_dc_advisory_count",
						"position": {
							"x": 730,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_infra_rogue_ap_count",
						"position": {
							"x": 1085,
							"y": 242,
							"w": 335,
							"h": 200
						},
						"type": "block"
					},
					{
						"item": "viz_infra_dc_trend",
						"position": {
							"x": 20,
							"y": 458,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_infra_sdwan_apps",
						"position": {
							"x": 730,
							"y": 458,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_infra_status_rollup",
						"position": {
							"x": 20,
							"y": 754,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_infra_psirt_exposure",
						"position": {
							"x": 730,
							"y": 754,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_infra_software_versions",
						"position": {
							"x": 20,
							"y": 1070,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_infra_rogue_containment",
						"position": {
							"x": 730,
							"y": 1070,
							"w": 690,
							"h": 280
						},
						"type": "block"
					},
					{
						"item": "viz_infra_secure_endpoint_incidents",
						"position": {
							"x": 20,
							"y": 1366,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_infra_duo_blocked_posture",
						"position": {
